import{_ as d,o as a,c as o,a3 as e}from"./chunks/framework.D81Tvp8W.js";const b=JSON.parse('{"title":"NoSQL 数据库","description":"","frontmatter":{"title":"NoSQL 数据库","date":"2025-09-02T00:00:00.000Z","categories":["backend","NoSQL"],"tags":["后端","NoSQL"]},"headers":[],"relativePath":"backend/NoSQL/index.md","filePath":"backend/NoSQL/index.md","lastUpdated":1786872962000}'),r={name:"backend/NoSQL/index.md"};function n(l,t,s,h,i,S){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="📄-nosql-数据库" tabindex="-1">📄 NoSQL 数据库 <a class="header-anchor" href="#📄-nosql-数据库" aria-label="Permalink to &quot;📄 NoSQL 数据库&quot;">​</a></h1><p>NoSQL（Not Only SQL）是非关系型数据库的统称，以 <strong>灵活的数据模型</strong> 和 <strong>水平扩展</strong> 见长，适合海量数据和高并发场景。</p><hr><h2 id="📚-目录导航" tabindex="-1">📚 目录导航 <a class="header-anchor" href="#📚-目录导航" aria-label="Permalink to &quot;📚 目录导航&quot;">​</a></h2><ul><li><a href="./MongoDB技术解析.html">🍃 MongoDB 技术解析</a> —— 最流行的文档型 NoSQL，从单机到分布式</li></ul><hr><h2 id="🧠-一、nosql-的四大类型" tabindex="-1">🧠 一、NoSQL 的四大类型 <a class="header-anchor" href="#🧠-一、nosql-的四大类型" aria-label="Permalink to &quot;🧠 一、NoSQL 的四大类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>代表</th><th>数据模型</th><th>典型场景</th></tr></thead><tbody><tr><td><strong>文档型</strong></td><td>MongoDB</td><td>JSON 文档</td><td>灵活结构、内容管理</td></tr><tr><td><strong>键值型</strong></td><td>Redis</td><td>Key-Value</td><td>缓存、会话、计数器</td></tr><tr><td><strong>列族型</strong></td><td>Cassandra、HBase</td><td>列簇</td><td>海量时序、大数据</td></tr><tr><td><strong>图数据库</strong></td><td>Neo4j</td><td>节点 + 关系</td><td>社交网络、推荐</td></tr></tbody></table><hr><h2 id="⚖️-二、nosql-vs-rdbms" tabindex="-1">⚖️ 二、NoSQL vs RDBMS <a class="header-anchor" href="#⚖️-二、nosql-vs-rdbms" aria-label="Permalink to &quot;⚖️ 二、NoSQL vs RDBMS&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>NoSQL</th><th>关系型（RDBMS）</th></tr></thead><tbody><tr><td>数据模型</td><td>灵活、动态</td><td>固定表结构</td></tr><tr><td>事务</td><td>弱（最终一致）</td><td>强 ACID</td></tr><tr><td>扩展</td><td>天然水平扩展</td><td>以垂直扩展为主</td></tr><tr><td>查询</td><td>各自方言</td><td>SQL 标准</td></tr><tr><td>适用</td><td>高并发、海量、灵活结构</td><td>强一致性业务</td></tr></tbody></table><blockquote><p>💡 完整对比见 <a href="./../RDBMS/">RDBMS 指南</a>。</p></blockquote><hr><h2 id="🎯-三、何时选-nosql" tabindex="-1">🎯 三、何时选 NoSQL？ <a class="header-anchor" href="#🎯-三、何时选-nosql" aria-label="Permalink to &quot;🎯 三、何时选 NoSQL？&quot;">​</a></h2><ul><li>数据结构经常变化 → 文档型</li><li>需要超低延迟缓存 → 键值型</li><li>海量写入、按时间查询 → 列族型</li><li>强关系网络 → 图数据库</li></ul><hr>',16)])])}const N=d(r,[["render",n]]);export{b as __pageData,N as default};
